mapper.select:
SELECT i.id, i.code as code, i.cfg_id, i.invoice_type as invoiceType, i.shop_id as shopId, i.so_id, i.so_code as soCode, i.platform_code as platformCode, i.template_type as templateType, i.status as status, i.no as no, i.start_code as startCode, i.bill_create_time as billCreateTime, i.remark as remark, case when i.invoice_type = 'nfe' then att.attach_url else i.file_url end as fileUrl, i.upload_status as uploadStatus, i.upload_time as uploadTime, id.id as detailId, id.sku_id, id.product_name as productName, id.sku_no as skuNo, si.name as shopName, i.invoice_nature as invoiceNature, i.company_name as companyName, i.seller_tax_no as sellerTaxNo, i.platform_invoice_no as platformInvoiceNo FROM invoice_info i left join invoice_detail id on i.id = id.main_id and id.is_deleted = false left join shop_info si on i.shop_id = si.id and si.disabled = false left join attachment att on i.id = att.business_id and att.is_deleted = false and att.type = 'invoice_info_pdf' WHERE ${params.sqlMap.default} and i.is_deleted=FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
i.create_time DESC
